-- 0085: 장면 이미지(영상용) 프롬프트를 DB에 저장 — 스타일 세트(art_styles) + 장면별 프롬프트(scene_prompts, 장면 영상 활동 칸에 연결)
-- 이미지 제작 화면에서 Lesson·활동을 고르면 프롬프트를 불러와 바로 만들 수 있다. 본사(hq) 전용. L9 영상 4편(19장) 시드 포함.
create table if not exists public.art_styles (
  id uuid primary key default gen_random_uuid(),
  name text not null unique,
  style text not null default '',
  avoid text not null default '',
  chars jsonb not null default '[]'::jsonb,
  created_at timestamptz not null default now()
);
create table if not exists public.scene_prompts (
  id uuid primary key default gen_random_uuid(),
  unit_id uuid not null references public.units(id) on delete cascade,
  step_id uuid not null references public.flow_steps(id) on delete cascade,
  seq int not null,
  lines text not null default '',        -- 이 그림이 쓰이는 대사 줄 (예: 1-3)
  desc_ko text not null default '',      -- 장면 설명(한글)
  prompt text not null default '',       -- 장면 프롬프트(영어). 스타일·인물은 화면이 붙임
  file_name text not null default '',
  style_id uuid references public.art_styles(id) on delete set null,
  created_at timestamptz not null default now(),
  unique (step_id, seq)
);
create index if not exists scene_prompts_unit on public.scene_prompts(unit_id);
alter table public.art_styles enable row level security;
alter table public.scene_prompts enable row level security;
drop policy if exists art_styles_hq on public.art_styles; create policy art_styles_hq on public.art_styles for all using (is_hq()) with check (is_hq());
drop policy if exists scene_prompts_hq on public.scene_prompts; create policy scene_prompts_hq on public.scene_prompts for all using (is_hq()) with check (is_hq());

do $do$
declare v_unit uuid; v_style uuid; v_n int;
begin
  insert into art_styles(name, style, avoid, chars)
  values ('비상 초5 영어 L9', $j$Semi-flat digital storybook illustration in the style of a modern international English-language textbook animation: soft textured shading and subtle grain, clean smooth outlines, warm saturated colors with fresh greens and sky blues, large expressive round eyes, rosy cheeks, natural proportions of upper-elementary children, diverse international cast, detailed but uncluttered background, no text, no letters, no numbers$j$, $j$school playground, pond, fish pool, easel, basketball hoop, school building, text, letters, words, numbers, watermark, logo, Korean or East Asian setting, hanbok, Korean signs, manga style, anime style, chibi, realistic photo, 3D render, scary, dark, extra fingers, distorted faces, brand names$j$, $j$[{"name": "Jun", "desc": "Cartoon boy about 11 years old, light-skinned, wavy dark brown hair with a side fringe, thin round glasses, navy blue puffer hoodie with white drawstrings, bright talkative smile"}, {"name": "Mom", "desc": "Cartoon mother in her late 30s, light-skinned, shoulder-length wavy chestnut hair, olive green cardigan and jeans, calm kind expression"}, {"name": "Clerk", "desc": "Cartoon shop clerk woman, medium-brown skin, dark curly hair tied back, coral apron with a blank name badge, friendly smile"}, {"name": "Sam", "desc": "Cartoon boy about 11 years old, light-skinned, tousled brown hair, light blue button shirt, curious expression"}, {"name": "Pablo", "desc": "Cartoon boy about 11 years old, tan skin, dark wavy hair, orange t-shirt, cheerful expression"}]$j$::jsonb)
  on conflict (name) do update set style = excluded.style, avoid = excluded.avoid, chars = excluded.chars
  returning id into v_style;
  select u.id into v_unit from units u join books b on b.id = u.book_id where b.title = '비상교육 초5 영어' and u.no = 9;
  if v_unit is null then raise notice 'L9 unit not found - scene prompts not seeded'; return; end if;
  insert into scene_prompts(unit_id, step_id, seq, lines, desc_ko, prompt, file_name, style_id)
  select v_unit, s.id, x.seq, x.lines, x.desc_ko, x.prompt, x.file_name, v_style
    from jsonb_to_recordset($j$[{"lesson": 1, "pos": 7, "seq": 1, "lines": "1-3", "desc_ko": "소풍 가방을 멘 준이 엄마 옆에서 신나게 걷는 가게 앞. 엄마는 쇼핑 목록 종이를 들고 있음", "prompt": "Jun with a small backpack walks happily next to his mom in front of a clothing store entrance, mom holds a shopping list paper, excited mood. The setting is a clothing store (shop interior, or the shop entrance if stated) - NOT a school, NOT a playground, NOT a pond or garden.", "file_name": "l9-1-8-1"}, {"lesson": 1, "pos": 7, "seq": 2, "lines": "4-5", "desc_ko": "가게 안, 점원이 웃으며 엄마와 준이에게 다가와 말을 거는 장면, 엄마가 고개를 끄덕임", "prompt": "Inside a bright, cozy clothing store with shelves of hats, sunglasses, jackets, shorts, socks and shoes, the clerk smiles and walks toward Jun and his mom to greet them, mom nods politely. The setting is a clothing store (shop interior, or the shop entrance if stated) - NOT a school, NOT a playground, NOT a pond or garden.", "file_name": "l9-1-8-2"}, {"lesson": 1, "pos": 7, "seq": 3, "lines": "6-7", "desc_ko": "준이가 선글라스 진열대를 가리키고, 점원이 여러 선글라스를 손으로 보여 줌", "prompt": "Jun points at a display of sunglasses, the clerk shows several cool sunglasses with her hand, a bright, cozy clothing store with shelves of hats, sunglasses, jackets, shorts, socks and shoes. The setting is a clothing store (shop interior, or the shop entrance if stated) - NOT a school, NOT a playground, NOT a pond or garden.", "file_name": "l9-1-8-3"}, {"lesson": 1, "pos": 7, "seq": 4, "lines": "8-9", "desc_ko": "점원이 선글라스 한 개를 준이에게 건네고, 준이가 손에 들고 색깔을 살펴보며 마음에 들어 하는 표정", "prompt": "The clerk hands a pair of sunglasses to Jun, Jun holds them up and looks at the color with a pleased face. The setting is a clothing store (shop interior, or the shop entrance if stated) - NOT a school, NOT a playground, NOT a pond or garden.", "file_name": "l9-1-8-4"}, {"lesson": 1, "pos": 7, "seq": 5, "lines": "10-11", "desc_ko": "준이가 선글라스를 들고 점원에게 가격을 묻고, 점원이 손가락으로 가격표(숫자 없는 빈 가격표)를 가리킴", "prompt": "Jun holding sunglasses asks the clerk a question, the clerk points to a blank price tag next to the sunglasses, mom watches. The setting is a clothing store (shop interior, or the shop entrance if stated) - NOT a school, NOT a playground, NOT a pond or garden.", "file_name": "l9-1-8-5"}, {"lesson": 1, "pos": 7, "seq": 6, "lines": "12-13", "desc_ko": "엄마가 엄지를 세우고, 준이가 선글라스를 얼굴에 쓰고 활짝 웃으며 계산대로 향함", "prompt": "Mom gives a thumbs up, Jun wears the sunglasses and smiles broadly, heading to the cash register. The setting is a clothing store (shop interior, or the shop entrance if stated) - NOT a school, NOT a playground, NOT a pond or garden.", "file_name": "l9-1-8-6"}, {"lesson": 1, "pos": 8, "seq": 1, "lines": "1-2", "desc_ko": "준이가 모자를 손에 들고 만족스럽게 보는 장면, 엄마가 옆에 서 있음", "prompt": "Jun holds a nice hat and looks at it happily, mom stands beside him, clothing store. The setting is a clothing store (shop interior, or the shop entrance if stated) - NOT a school, NOT a playground, NOT a pond or garden.", "file_name": "l9-1-9-1"}, {"lesson": 1, "pos": 8, "seq": 2, "lines": "3-5", "desc_ko": "준이가 하이킹용 튼튼한 신발을 들어 보이며 사겠다고 신나게 말하는 장면", "prompt": "Jun holds up a pair of sturdy hiking shoes with excitement, hat already in his other arm, clothing store. The setting is a clothing store (shop interior, or the shop entrance if stated) - NOT a school, NOT a playground, NOT a pond or garden.", "file_name": "l9-1-9-2"}, {"lesson": 1, "pos": 8, "seq": 3, "lines": "6", "desc_ko": "엄마가 계산기(숫자 없음)를 보며 눈이 동그래져 놀라는 표정, 준이는 어리둥절", "prompt": "Mom looks at a calculator with wide surprised eyes, Jun looks confused beside her. The setting is a clothing store (shop interior, or the shop entrance if stated) - NOT a school, NOT a playground, NOT a pond or garden.", "file_name": "l9-1-9-3"}, {"lesson": 1, "pos": 8, "seq": 4, "lines": "7-8", "desc_ko": "준이가 점원에게 신발을 가리키며 가격을 묻고, 점원이 손가락으로 빈 가격표를 가리킴", "prompt": "Jun points at the shoes and asks the clerk, the clerk points to a blank price tag on the shoe box. The setting is a clothing store (shop interior, or the shop entrance if stated) - NOT a school, NOT a playground, NOT a pond or garden.", "file_name": "l9-1-9-4"}, {"lesson": 1, "pos": 8, "seq": 5, "lines": "9-10", "desc_ko": "엄마가 깜짝 놀라 두 손을 볼에 대고, 준이는 머리를 감싸 쥐며 '아이고' 하는 표정, 점원은 난처하게 웃음", "prompt": "Mom is shocked with both hands on her cheeks, Jun holds his head with an 'oh no' face, the clerk smiles awkwardly. The setting is a clothing store (shop interior, or the shop entrance if stated) - NOT a school, NOT a playground, NOT a pond or garden.", "file_name": "l9-1-9-5"}, {"lesson": 2, "pos": 3, "seq": 1, "lines": "1-4", "desc_ko": "샘이 배(보트)처럼 생긴 우스운 신발을 들고 웃음을 터뜨리는 장면", "prompt": "Sam laughs while holding a pair of funny shoes shaped like little boats, clothing store shelves behind. The setting is a clothing store (shop interior, or the shop entrance if stated) - NOT a school, NOT a playground, NOT a pond or garden.", "file_name": "l9-2-4-1"}, {"lesson": 2, "pos": 3, "seq": 2, "lines": "5-6", "desc_ko": "샘이 신발을 신어 봐도 되냐고 묻고, 점원이 손짓으로 '그럼요' 하는 장면", "prompt": "Sam asks the clerk with a curious face while holding the boat-shaped shoes, the clerk gestures kindly to go ahead. The setting is a clothing store (shop interior, or the shop entrance if stated) - NOT a school, NOT a playground, NOT a pond or garden.", "file_name": "l9-2-4-2"}, {"lesson": 2, "pos": 3, "seq": 3, "lines": "7-9", "desc_ko": "샘이 보트 모양 신발을 신고 서 있고, 점원이 '세일' 표지판(글자 없는 별 모양 표지)을 가리킴", "prompt": "Sam wearing the boat-shaped shoes, the clerk points to a star-shaped sale sign without any text. The setting is a clothing store (shop interior, or the shop entrance if stated) - NOT a school, NOT a playground, NOT a pond or garden.", "file_name": "l9-2-4-3"}, {"lesson": 2, "pos": 3, "seq": 4, "lines": "10-11", "desc_ko": "샘이 엄지를 세우고 활짝 웃으며 신발 박스를 들고 계산대로 감", "prompt": "Sam gives a thumbs up with a big smile, carrying the shoe box to the cash register. The setting is a clothing store (shop interior, or the shop entrance if stated) - NOT a school, NOT a playground, NOT a pond or garden.", "file_name": "l9-2-4-4"}, {"lesson": 2, "pos": 4, "seq": 1, "lines": "1-3", "desc_ko": "점원이 파블로에게 다가가 말을 걸고, 파블로가 반바지 진열대를 가리킴", "prompt": "The clerk greets Pablo, Pablo points at shorts on a display, a bright, cozy clothing store with shelves of hats, sunglasses, jackets, shorts, socks and shoes. The setting is a clothing store (shop interior, or the shop entrance if stated) - NOT a school, NOT a playground, NOT a pond or garden.", "file_name": "l9-2-5-1"}, {"lesson": 2, "pos": 4, "seq": 2, "lines": "4-5", "desc_ko": "파블로가 반바지를 들어 보이며 가격을 묻고, 점원이 빈 가격표를 가리킴", "prompt": "Pablo holds up a pair of shorts and asks the clerk, the clerk points to a blank price tag. The setting is a clothing store (shop interior, or the shop entrance if stated) - NOT a school, NOT a playground, NOT a pond or garden.", "file_name": "l9-2-5-2"}, {"lesson": 2, "pos": 4, "seq": 3, "lines": "6", "desc_ko": "점원이 반바지와 어울리는 모자를 건네며 입어 보라고 권하는 장면", "prompt": "The clerk hands Pablo a cap to wear with the shorts, suggesting he try them on. The setting is a clothing store (shop interior, or the shop entrance if stated) - NOT a school, NOT a playground, NOT a pond or garden.", "file_name": "l9-2-5-3"}, {"lesson": 2, "pos": 4, "seq": 4, "lines": "7-8", "desc_ko": "반바지와 모자를 착용한 파블로가 거울 앞에서 놀라고 기뻐하며 서 있고, 점원이 엄지를 세움", "prompt": "Pablo wearing shorts and a cap stands in front of a mirror amazed and happy, the clerk gives a thumbs up. The setting is a clothing store (shop interior, or the shop entrance if stated) - NOT a school, NOT a playground, NOT a pond or garden.", "file_name": "l9-2-5-4"}]$j$::jsonb) as x(lesson int, pos int, seq int, lines text, desc_ko text, prompt text, file_name text)
    join flow_lessons fl on fl.unit_id = v_unit and fl.no = x.lesson
    join flow_steps s on s.lesson_id = fl.id and s.pos = x.pos and s.kind in ('scene', 'scenerep')
  on conflict (step_id, seq) do nothing;
  get diagnostics v_n = row_count;
  raise notice 'scene prompts seeded: % (expected 19)', v_n;
end $do$;
